using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using System.Collections.Generic;
using System.IO;
using System.Linq;

public static class TidehavenBuilder {
 const string Root="Assets/Tidehaven"; static Material ground;static Transform nature,reef,buildings;static Dictionary<string,Material> palette;
 [System.Serializable]class Palette{public Entry[] items;}[System.Serializable]class Entry{public string name;public float r,g,b,a;}
 static Color Hex(string s){ColorUtility.TryParseHtmlString(s,out Color c);return c;}
 static Material Mat(string name,Color c){string p=Root+"/Materials/"+name.Replace('/','_')+".mat";Material m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,p);}m.color=c;m.SetFloat("_Smoothness",.12f);m.SetFloat("_Cull",0);m.enableInstancing=true;return m;}
 static Mesh SaveMesh(Mesh m,string name){m.name=name;string p=Root+"/Meshes/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(p);if(old){EditorUtility.CopySerialized(m,old);return old;}AssetDatabase.CreateAsset(m,p);return m;}
 static GameObject MeshObj(string name,Mesh m,Material mat,Transform parent=null,bool collision=false){var go=new GameObject(name);go.transform.parent=parent;go.AddComponent<MeshFilter>().sharedMesh=m;go.AddComponent<MeshRenderer>().sharedMaterial=mat;if(collision)go.AddComponent<MeshCollider>().sharedMesh=m;return go;}
 static Bounds BoundsOf(GameObject o){var rs=o.GetComponentsInChildren<Renderer>();Bounds b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 static GameObject Model(string name,Vector3 p,float height,float yaw,Transform parent,bool collide=false){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Models/"+name+".fbx");if(!prefab)throw new System.Exception("Missing model "+name);var go=new GameObject(name);go.transform.SetParent(parent);var imported=(GameObject)PrefabUtility.InstantiatePrefab(prefab);imported.transform.SetParent(go.transform,false);go.transform.rotation=Quaternion.Euler(0,yaw,0);Bounds b=BoundsOf(go);go.transform.localScale*=height/Mathf.Max(.01f,b.size.y);b=BoundsOf(go);go.transform.position+=p-new Vector3(b.center.x,b.min.y,b.center.z);
 foreach(var r in go.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>{if(m&&palette.TryGetValue(m.name,out var mapped))return mapped;return Mat("Fallback",Hex("#74845B"));}).ToArray();}
 if(collide){b=BoundsOf(go);var c=go.AddComponent<BoxCollider>();c.center=go.transform.InverseTransformPoint(b.center);c.size=new Vector3(b.size.x/go.transform.lossyScale.x,b.size.y/go.transform.lossyScale.y,b.size.z/go.transform.lossyScale.z)*.75f;}
 return go;}
 static Vector3 Land(float x,float z){return new Vector3(x,TidehavenGame.Ground(x,z),z);}
 static Mesh Terrain(){int n=180;var v=new Vector3[(n+1)*(n+1)];var c=new Color[v.Length];var uv=new Vector2[v.Length];var tris=new int[n*n*6];for(int z=0;z<=n;z++)for(int x=0;x<=n;x++){int i=z*(n+1)+x;float wx=(x/(float)n-.5f)*110,wz=(z/(float)n-.5f)*95;v[i]=Land(wx,wz);uv[i]=new Vector2(wx,wz);float d=wz-TidehavenGame.Shore(wx);Color sand=Color.Lerp(Hex("#B7A675"),Hex("#D4C28A"),Mathf.PerlinNoise(wx*.2f+40,wz*.2f+40));c[i]=Color.Lerp(Hex("#819C89"),sand,Mathf.Clamp01((d+10)/8));}int k=0;for(int z=0;z<n;z++)for(int x=0;x<n;x++){int i=z*(n+1)+x;tris[k++]=i;tris[k++]=i+n+1;tris[k++]=i+1;tris[k++]=i+1;tris[k++]=i+n+1;tris[k++]=i+n+2;}var m=new Mesh();m.vertices=v;m.colors=c;m.uv=uv;m.triangles=tris;m.RecalculateNormals();return SaveMesh(m,"CoastalTerrain");}
 static void Meadow(string name,float cx,float cz,float rx,float rz,int seed){Random.InitState(seed);int rings=12,n=80;var vs=new List<Vector3>();var cs=new List<Color>();var ts=new List<int>();for(int r=0;r<=rings;r++)for(int j=0;j<=n;j++){float a=j/(float)n*Mathf.PI*2;float t=r/(float)rings;float wobble=1+.09f*Mathf.Sin(a*5+seed)+.07f*Mathf.Sin(a*9);float x=cx+Mathf.Cos(a)*rx*t*wobble,z=cz+Mathf.Sin(a)*rz*t*wobble;vs.Add(Land(x,z)+Vector3.up*.025f);Color color=Color.Lerp(Hex("#40763A"),Hex("#80A94A"),Mathf.PerlinNoise(x*.5f,z*.5f));cs.Add(Color.Lerp(color,Hex("#B8B875"),Mathf.Pow(t,8)*.65f));}for(int r=0;r<rings;r++)for(int j=0;j<n;j++){int i=r*(n+1)+j;ts.AddRange(new[]{i,i+1,i+n+1,i+1,i+n+2,i+n+1});}var mesh=new Mesh();mesh.SetVertices(vs);mesh.SetColors(cs);mesh.SetTriangles(ts,0);mesh.RecalculateNormals();MeshObj(name,SaveMesh(mesh,name),ground,nature);
 // Combined tapered grass blades, with small ivory flowers at the meadow edges.
 vs.Clear();cs.Clear();ts.Clear();for(int k=0;k<250;k++){float a=Random.value*Mathf.PI*2,t=Mathf.Sqrt(Random.value);float x=cx+Mathf.Cos(a)*rx*t,z=cz+Mathf.Sin(a)*rz*t;Vector3 p=Land(x,z)+Vector3.up*.04f;for(int b=0;b<3;b++){float ang=Random.value*6.28f;Vector3 side=new Vector3(Mathf.Cos(ang),0,Mathf.Sin(ang))*.05f;float h=Random.Range(.17f,.43f);int i=vs.Count;vs.Add(p-side);vs.Add(p+side);vs.Add(p+Vector3.up*h+side*1.8f);ts.AddRange(new[]{i,i+2,i+1});Color col=Color.Lerp(Hex("#376C37"),Hex("#9AB858"),Random.value);cs.Add(col*.7f);cs.Add(col*.7f);cs.Add(col);}
 if(k%8==0){for(int pet=0;pet<5;pet++){float ang=pet*1.2566f;Vector3 center=p+Vector3.up*.21f,tip=center+new Vector3(Mathf.Cos(ang),.015f,Mathf.Sin(ang))*.1f;Vector3 side=new Vector3(-Mathf.Sin(ang),0,Mathf.Cos(ang))*.04f;int i=vs.Count;vs.Add(center);vs.Add(tip-side);vs.Add(tip+side);ts.AddRange(new[]{i,i+2,i+1});cs.Add(Hex("#E2BA4C"));cs.Add(Hex("#FFF8DD"));cs.Add(Hex("#FFF8DD"));}}}
 mesh=new Mesh();mesh.SetVertices(vs);mesh.SetColors(cs);mesh.SetTriangles(ts,0);mesh.RecalculateNormals();MeshObj(name+" grasses",SaveMesh(mesh,name+"Grass"),ground,nature);
 }
 [MenuItem("Tidehaven/Build Coral Cove")]
 public static string Build(){ if(File.Exists(Root+"/Scenes/CoralCove.unity")) return "CoralCove already exists. Open the saved scene; the generator will not overwrite your scene edits.";
 Directory.CreateDirectory(Root+"/Materials");Directory.CreateDirectory(Root+"/Meshes");Directory.CreateDirectory(Root+"/Scenes");
 palette=new Dictionary<string,Material>();var pal=JsonUtility.FromJson<Palette>(File.ReadAllText(Root+"/Models/palette.json"));foreach(var e in pal.items)palette[e.name]=Mat(e.name,new Color(e.r,e.g,e.b,1).gamma);
 var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
 nature=new GameObject("Nature • palms, grasses and shore rocks").transform;reef=new GameObject("Living reef").transform;buildings=new GameObject("Harbor").transform;
 ground=new Material(Shader.Find("Tidehaven/Coastal Ground"));AssetDatabase.CreateAsset(ground,Root+"/Materials/CoastalGround.mat");
 MeshObj("Sandy coast and seabed",Terrain(),ground,null,true);
 foreach(string id in AssetDatabase.FindAssets("t:UniversalRenderPipelineAsset")){var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(AssetDatabase.GUIDToAssetPath(id));rp.supportsCameraDepthTexture=true;rp.supportsCameraOpaqueTexture=true;rp.shadowDistance=90;EditorUtility.SetDirty(rp);}
 var waterBase=AssetDatabase.LoadAssetAtPath<Material>("Assets/Shaders/Uber Stylized Water/Template Materials/UWa-Template-Tropical.mat");var water=new Material(waterBase);water.name="Coral Cove • Showcase 4 tropical water";water.DisableKeyword("_ENABLEPLANERREFLECTION");water.SetColor("_Color_Shallow",new Color(.14f,.66f,.57f,.23f));water.SetColor("_Color_Deep",new Color(.015f,.30f,.31f,.86f));water.SetFloat("_Depth_Distance",2.8f);water.SetFloat("_SL_Ammount",1.5f);water.SetFloat("_SL_Thickness",.4f);water.SetFloat("_Normal_Strength",.12f);AssetDatabase.CreateAsset(water,Root+"/Materials/CoveWater.mat");var ocean=GameObject.CreatePrimitive(PrimitiveType.Plane);ocean.name="Uber Stylized Water • clear lagoon";ocean.transform.localScale=new Vector3(11,1,10);Object.DestroyImmediate(ocean.GetComponent<Collider>());ocean.GetComponent<Renderer>().sharedMaterial=water;
 Meadow("Western palm grove",-13,11,8,6,12);Meadow("Eastern berry grove",13,11,7,6,29);Meadow("Northern gardens",0,23,15,5,41);
 Random.InitState(7);for(int i=0;i<18;i++){float x=i<9?Random.Range(-21,-7):Random.Range(8,22),z=Random.Range(8,21);Model("Palm",Land(x,z),Random.Range(4.3f,6.5f),Random.Range(0,360),nature);}
 for(int i=0;i<22;i++){float x=i<11?Random.Range(-20,-7):Random.Range(8,21),z=Random.Range(6,20);Model("BerryBush",Land(x,z),Random.Range(.65f,1.15f),Random.Range(0,360),nature);}
 for(int i=0;i<22;i++){float x=Random.Range(-25,25),z=i<12?Random.Range(20,25):TidehavenGame.Shore(x)+Random.Range(-1,7);if(Mathf.Abs(x)<4&&z<12)continue;Model("Boulder",Land(x,z)-Vector3.up*.12f,Random.Range(.6f,2.4f),Random.Range(0,360),nature,true);}
 Model("House",Land(-10,16),5.2f,8,buildings,true);Model("Shop",Land(17,17),4.8f,-12,buildings,true);Model("Dock",new Vector3(12,-1.4f,0),2.4f,0,buildings);
 for(int i=0;i<9;i++){float x=Random.Range(-17,19),z=Random.Range(-11,-3);Model(i%3==0?"Reef":"Coral",Land(x,z),Random.Range(.65f,1.15f),Random.Range(0,360),reef);}
 for(int i=0;i<22;i++){float x=Random.Range(-24,24),z=Random.Range(-14,-2);Model("Seagrass",Land(x,z),Random.Range(.35f,.75f),Random.Range(0,360),reef);}
 for(int i=0;i<12;i++){float x=Random.Range(-20,20),z=TidehavenGame.Shore(x)+Random.Range(.8f,3.3f);Model(i%3==0?"Starfish":"Crab",Land(x,z)+Vector3.up*.025f,i%3==0?.08f:.18f,Random.Range(0,360),nature);}
 var camGO=new GameObject("Main Camera",typeof(Camera),typeof(AudioListener),typeof(UniversalAdditionalCameraData));camGO.tag="MainCamera";var cam=camGO.GetComponent<Camera>();cam.orthographic=true;cam.orthographicSize=9.5f;cam.nearClipPlane=.1f;cam.farClipPlane=160;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Hex("#76B3AC");cam.GetUniversalAdditionalCameraData().renderPostProcessing=true;
 var sun=new GameObject("Warm morning sun",typeof(Light));var light=sun.GetComponent<Light>();light.type=LightType.Directional;light.intensity=1.65f;light.color=Hex("#FFF0CB");light.shadows=LightShadows.Soft;sun.transform.rotation=Quaternion.Euler(48,-35,0);RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=Hex("#A5C9D0");RenderSettings.ambientEquatorColor=Hex("#8DA69C");RenderSettings.ambientGroundColor=Hex("#62755F");RenderSettings.sun=light;
 var vol=new GameObject("Coastal color grade",typeof(Volume));var volume=vol.GetComponent<Volume>();volume.isGlobal=true;var profile=ScriptableObject.CreateInstance<VolumeProfile>();var tone=profile.Add<Tonemapping>();tone.mode.Override(TonemappingMode.ACES);var color=profile.Add<ColorAdjustments>();color.saturation.Override(6);color.contrast.Override(8);AssetDatabase.CreateAsset(profile,Root+"/Materials/CoastalGrade.asset");volume.sharedProfile=profile;
 var player=new GameObject("Fisherman • WASD to walk");player.transform.position=Land(0,5.5f);var visual=Model("Fisherman",player.transform.position,1.9f,180,player.transform);var anim=visual.GetComponentInChildren<Animator>();if(anim){var clip=AssetDatabase.LoadAllAssetsAtPath(Root+"/Models/Fisherman.fbx").OfType<AnimationClip>().FirstOrDefault(c=>!c.name.StartsWith("__"));if(clip)clip.SampleAnimation(anim.gameObject,0);Object.DestroyImmediate(anim);}var cc=player.AddComponent<CharacterController>();cc.height=1.75f;cc.radius=.24f;cc.center=Vector3.up*.9f;cc.stepOffset=.35f;cc.skinWidth=.025f;
 var game=new GameObject("Fishing • cast, bite and reel").AddComponent<TidehavenGame>();game.player=player.transform;game.visual=visual.transform;game.view=cam;cam.transform.position=player.transform.position+new Vector3(0,20,-14);cam.transform.rotation=Quaternion.LookRotation(new Vector3(0,-20,14));
 var rod=new GameObject("Fishing rod",typeof(LineRenderer));rod.transform.SetParent(player.transform,false);var lr=rod.GetComponent<LineRenderer>();lr.useWorldSpace=false;lr.positionCount=3;lr.SetPositions(new[]{new Vector3(.35f,1,0),new Vector3(.38f,1.8f,.8f),new Vector3(.39f,2.3f,1.7f)});lr.startWidth=.035f;lr.endWidth=.012f;lr.sharedMaterial=Mat("Bamboo rod",Hex("#866132"));var tip=new GameObject("Rod tip").transform;tip.parent=player.transform;tip.localPosition=new Vector3(.39f,2.3f,1.7f);game.rodTip=tip;
 var line=new GameObject("Fishing line",typeof(LineRenderer)).GetComponent<LineRenderer>();line.positionCount=24;line.startWidth=.012f;line.endWidth=.008f;line.sharedMaterial=Mat("Fishing line",Hex("#334D43"));line.enabled=false;game.fishingLine=line;var bob=GameObject.CreatePrimitive(PrimitiveType.Sphere);bob.name="Red fishing float";bob.transform.localScale=new Vector3(.13f,.20f,.13f);Object.DestroyImmediate(bob.GetComponent<Collider>());bob.GetComponent<Renderer>().sharedMaterial=Mat("Coral red float",Hex("#D76142"));bob.SetActive(false);game.bobber=bob.transform;
 for(int i=0;i<20;i++){float x=Random.Range(-20,20),z=Random.Range(-12,-2);var f=Model(i%4==0?"GoldenFish":"ReefFish",new Vector3(x,Mathf.Max(TidehavenGame.Ground(x,z)+.4f,-.7f),z),.13f,Random.Range(0,360),reef);game.fish.Add(f.transform);}
 EditorSceneManager.SaveScene(scene,Root+"/Scenes/CoralCove.unity");EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(Root+"/Scenes/CoralCove.unity",true)};AssetDatabase.SaveAssets();Selection.activeGameObject=player;return "Built CoralCove: "+scene.rootCount+" roots; 20 fish; fishing controls ready.";
 }
